(1037266, 124987, 29486, '<td valign="top">Nice lighting, semi interesting subject. Not bad...</td>', 'Nice lighting, semi interesting subject. Not bad...', '2004-11-30 00:43:47.000000', NULL, 1),
(1037268, 124506, 29486, '<td valign="top">Obviously a cute girl etc but the photo is not tack sharp. Looks like you tried some post processing but it just didn''t work. Look at the eyes.</td>', 'Obviously a cute girl etc but the photo is not tack sharp. Looks like you tried some post processing but it just didn''t work. Look at the eyes.', '2004-11-30 00:45:16.000000', NULL, 1),
(1037270, 124946, 29486, '<td valign="top">Good lighting, good angle, nice color. Beautiful photo.</td>', 'Good lighting, good angle, nice color. Beautiful photo.', '2004-11-30 00:45:57.000000', NULL, 1),
