(1037596, 124292, 29535, '<td valign="top">Nice!  Very original, I doubt I''ll see another abacus here, great shot.</td>', 'Nice!  Very original, I doubt I''ll see another abacus here, great shot.', '2004-11-30 05:14:30.000000', NULL, 1),
(1037599, 124545, 29535, '<td valign="top">The term electric eye on the front makes me believe this could be battery powered?  But I''ll give you the benefit of the doubt and give you the score this shot deserves.</td>', 'The term electric eye on the front makes me believe this could be battery powered?  But I''ll give you the benefit of the doubt and give you the score this shot deserves.', '2004-11-30 05:15:36.000000', NULL, 1),
