(1037604, 124042, 29535, '<td valign="top">Haha brilliant!  Some very original entries here, well done!</td>', 'Haha brilliant!  Some very original entries here, well done!', '2004-11-30 05:17:18.000000', NULL, 1),
(1037605, 122656, 29535, '<td valign="top">Nice idea, and good shot.  Well done!</td>', 'Nice idea, and good shot.  Well done!', '2004-11-30 05:17:34.000000', NULL, 1),
(1037606, 122388, 29535, '<td valign="top">Wow that''s a nice teapot, well done, good shot and quite original!</td>', 'Wow that''s a nice teapot, well done, good shot and quite original!', '2004-11-30 05:17:58.000000', NULL, 1),
(1037607, 124447, 29535, '<td valign="top">I don''t like the angle here, it''s too slanted.  But great idea so you get points for that.</td>', 'I don''t like the angle here, it''s too slanted.  But great idea so you get points for that.', '2004-11-30 05:18:29.000000', NULL, 1),
(1037608, 123278, 23251, '<td valign="top">There are things visable in the background that are very distracting, maybe they could have been cloned out.  Also the board is not level, it would help to rotate it.  The lighting is good.</td>', 'There are things visable in the background that are very distracting, maybe they could have been cloned out.  Also the board is not level, it would help to rotate it.  The lighting is good.', '2004-11-30 05:18:42.000000', NULL, 1),
(1037610, 122813, 29535, '<td valign="top">Nice!  Great idea and nice shot.  Strange how the backgrounds so crooked when the post isn''t, but the blur makes this irrelavant as it can hardly be seen. Well done!</td>', 'Nice!  Great idea and nice shot.  Strange how the backgrounds so crooked when the post isn''t, but the blur makes this irrelavant as it can hardly be seen. Well done!', '2004-11-30 05:19:16.000000', NULL, 1),
(1037611, 124524, 29535, '<td valign="top">Brilliant!  Nice and original, and a great shot.</td>', 'Brilliant!  Nice and original, and a great shot.', '2004-11-30 05:19:34.000000', NULL, 1),
(1037612, 124603, 29535, '<td valign="top">Well I don''t know about this one, microphones are elcectronic and therefore against the challenge statement, and I fail tos ee any low technology here.  It''s a shame, because it''s a great shot.</td>', 'Well I don''t know about this one, microphones are elcectronic and therefore against the challenge statement, and I fail tos ee any low technology here.  It''s a shame, because it''s a great shot.', '2004-11-30 05:20:29.000000', NULL, 1),
(1037613, 124464, 29535, '<td valign="top">Nice!  Sepia tone works well, good foreground and back.</td>', 'Nice!  Sepia tone works well, good foreground and back.', '2004-11-30 05:20:50.000000', NULL, 1),
(1037617, 123777, 29535, '<td valign="top">That''s a modern can opener silly :p  The older ones are those awful things you have to put all your strength behind.  But this is still pretty low tech as they have electric ones nowm, so great idea and well done.</td>', 'That''s a modern can opener silly :p  The older ones are those awful things you have to put all your strength behind.  But this is still pretty low tech as they have electric ones nowm, so great idea and well done.', '2004-11-30 05:22:12.000000', NULL, 1),
(1037618, 124776, 29535, '<td valign="top">Good idea!  Nice shot too, well done!</td>', 'Good idea!  Nice shot too, well done!', '2004-11-30 05:22:26.000000', NULL, 1),
(1037619, 124972, 29535, '<td valign="top">Very original, and great colour balance.  Brilliant shot!</td>', 'Very original, and great colour balance.  Brilliant shot!', '2004-11-30 05:22:47.000000', NULL, 1),
(1037620, 121877, 29535, '<td valign="top">Lot''s of pestle and mortars here :p  But this is one of the best, well done.  Great idea and great shot!</td>', 'Lot''s of pestle and mortars here :p  But this is one of the best, well done.  Great idea and great shot!', '2004-11-30 05:23:22.000000', NULL, 1),
(1037621, 124932, 29535, '<td valign="top">Nice idea, original!</td>', 'Nice idea, original!', '2004-11-30 05:23:36.000000', NULL, 1),
(1037623, 124623, 29535, '<td valign="top">Nice idea!  And a great shot too, why do you have such a rusty can opener? :p</td>', 'Nice idea!  And a great shot too, why do you have such a rusty can opener? :p', '2004-11-30 05:24:05.000000', NULL, 1),
(1037624, 123907, 29535, '<td valign="top">The crop is a little tight, I''d have liked to see the wheel and the roof not cut off slightly, but great idea and good lighting.</td>', 'The crop is a little tight, I''d have liked to see the wheel and the roof not cut off slightly, but great idea and good lighting.', '2004-11-30 05:24:32.000000', NULL, 1);
