(1037877, 124883, 27574, '<td valign="top">beautiful composition and range of colors, I think I would have punched up the colors, though.....they are a bit dull.</td>', 'beautiful composition and range of colors, I think I would have punched up the colors, though.....they are a bit dull.', '2004-11-30 09:55:04.000000', NULL, 1),
(1037879, 122003, 18194, '<td valign="top">This is a nice composition.  It is suffering from too much compression, this shows up as the noise along the lines. This also adds a bit of faint lines in the sky.  When you save the photo it would help a lot to use a higher quality setting.</td>', 'This is a nice composition.  It is suffering from too much compression, this shows up as the noise along the lines. This also adds a bit of faint lines in the sky.  When you save the photo it would help a lot to use a higher quality setting.', '2004-11-30 09:55:27.000000', NULL, 1),
