(1038175, 123050, 208, '<td valign="top">I really like the framing here, but those *very* black eyes kind of creep me out and draw lots of focus.</td>', 'I really like the framing here, but those *very* black eyes kind of creep me out and draw lots of focus.', '2004-11-30 12:48:48.000000', NULL, 1),
(1038178, 123050, 24183, '<td valign="top">Would have liked to see more of the horses nose.</td>', 'Would have liked to see more of the horses nose.', '2004-11-30 12:49:16.000000', NULL, 1),
(1038181, 124968, 24846, '<td valign="top">My favorite tool. Nice shadow but would have adjusted lighting to achieve less light off the tape. Good luck...</td>', 'My favorite tool. Nice shadow but would have adjusted lighting to achieve less light off the tape. Good luck...', '2004-11-30 12:49:51.000000', NULL, 1),
(1038184, 124697, 208, '<td valign="top">My eyes go all over the photo without really picking out a specific subject. The tractor and house and mountain brush all run together.</td>', 'My eyes go all over the photo without really picking out a specific subject. The tractor and house and mountain brush all run together.', '2004-11-30 12:50:30.000000', NULL, 1),
(1038186, 123451, 25024, '<td valign="top">Beautiful composition - is this surreal look post processing? I would be very interested to find out after the voting.</td>', 'Beautiful composition - is this surreal look post processing? I would be very interested to find out after the voting.', '2004-11-30 12:51:17.000000', NULL, 1),
(1038189, 124965, 23478, '<td valign="top">The thumbbnail of this is awesome... I was a little dissappointed to see that it is a bit out of focus.  Great idea.</td>', 'The thumbbnail of this is awesome... I was a little dissappointed to see that it is a bit out of focus.  Great idea.', '2004-11-30 12:51:47.000000', NULL, 1),
(1038192, 123484, 208, '<td valign="top">I usually like the high key effect, but for some reason it doesn''t work for me here. Sorry I can''t be specific as to why. I''d also leave more space on the sides. It''s a cool experiment, though.</td>', 'I usually like the high key effect, but for some reason it doesn''t work for me here. Sorry I can''t be specific as to why. I''d also leave more space on the sides. It''s a cool experiment, though.', '2004-11-30 12:52:55.000000', NULL, 1),
(1038196, 122834, 23478, '<td valign="top">Great collor and very well composed.</td>', 'Great collor and very well composed.', '2004-11-30 12:53:32.000000', NULL, 1),
(1038203, 121778, 23478, '<td valign="top">Great photo, this just needed a different background to make it a winner.  The blinds distact quite a bit.</td>', 'Great photo, this just needed a different background to make it a winner.  The blinds distact quite a bit.', '2004-11-30 12:54:47.000000', NULL, 1),
(1038204, 124351, 23478, '<td valign="top">great photo, this just has a bit too much grain in it.</td>', 'great photo, this just has a bit too much grain in it.', '2004-11-30 12:55:25.000000', NULL, 1),
