(1038219, 124785, 25024, '<td valign="top">Lovely idea, well executed and great caption, I like the ''mousehole'' - unfortunately that diagonal behind is very distracting. I wish you well.</td>', 'Lovely idea, well executed and great caption, I like the ''mousehole'' - unfortunately that diagonal behind is very distracting. I wish you well.', '2004-11-30 12:57:42.000000', NULL, 1),
(1038225, 122857, 208, '<td valign="top">Well, the selective desaturation helps make the wheel pop, but it also makes the scene feel contrived (especially since the block attaching the wheel to the bricks looks b&amp;w). Would a more blurred background be more effective?</td>', 'Well, the selective desaturation helps make the wheel pop, but it also makes the scene feel contrived (especially since the block attaching the wheel to the bricks looks b&w). Would a more blurred background be more effective?', '2004-11-30 12:58:35.000000', NULL, 1),
