(1038658, 124942, 24183, '<td valign="top">I like the feel of the photo, although I may like to see it from a different angl.  and maybe from further back.</td>', 'I like the feel of the photo, although I may like to see it from a different angl.  and maybe from further back.', '2004-11-30 16:41:12.000000', NULL, 1),
(1038662, 123481, 24183, '<td valign="top">Great stoped action.  I also like the shadow on the back  wall.  I would clone out the elephant, and crop some of the left of the photo.  Then it would be perfect.  Elephant should not be in there at all.  Hurts the photo</td>', 'Great stoped action.  I also like the shadow on the back  wall.  I would clone out the elephant, and crop some of the left of the photo.  Then it would be perfect.  Elephant should not be in there at all.  Hurts the photo', '2004-11-30 16:43:48.000000', NULL, 1),
(1038666, 122488, 24183, '<td valign="top">I love the colors and the border works nice with this.  I think if you used a white piece of paper and not carpet for the b/g it would have been better.  I think the lines take away from it.</td>', 'I love the colors and the border works nice with this.  I think if you used a white piece of paper and not carpet for the b/g it would have been better.  I think the lines take away from it.', '2004-11-30 16:45:21.000000', NULL, 1),
(1038667, 122432, 24183, '<td valign="top">Nice dof, nice lighting, nice line.  You cant inprove this one too much.8</td>', 'Nice dof, nice lighting, nice line.  You cant inprove this one too much.8', '2004-11-30 16:46:39.000000', NULL, 1),
(1038669, 124460, 24183, '<td valign="top">Closer, would have been better, more light so your shutter speed could have been faster to stop the popcorn,  maybe do away ith the glasses</td>', 'Closer, would have been better, more light so your shutter speed could have been faster to stop the popcorn,  maybe do away ith the glasses', '2004-11-30 16:48:08.000000', NULL, 1),
(1038672, 123906, 24183, '<td valign="top">I think this is a little to plain,  Maybe in color with a dark blue sky and darken up the cloud so it looks like it has deeper shadows</td>', 'I think this is a little to plain,  Maybe in color with a dark blue sky and darken up the cloud so it looks like it has deeper shadows', '2004-11-30 16:49:33.000000', NULL, 1),
(1038673, 123907, 24183, '<td valign="top">A little to close to the suject I think,  maybe backup a little and scale down the lighting some</td>', 'A little to close to the suject I think,  maybe backup a little and scale down the lighting some', '2004-11-30 16:51:13.000000', NULL, 1),
(1038675, 124654, 24183, '<td valign="top">kind of hard to see the glass mabe more dof so  it would be clearer.  Or maybe add some side lighting to bounce off the glass to make it more visible</td>', 'kind of hard to see the glass mabe more dof so  it would be clearer.  Or maybe add some side lighting to bounce off the glass to make it more visible', '2004-11-30 16:52:59.000000', NULL, 1),
(1038676, 124779, 24183, '<td valign="top">I think maybe you should Take away some of the grain, and I''m not sure of the water spots on the glass, but it has very good lighting.</td>', 'I think maybe you should Take away some of the grain, and I''m not sure of the water spots on the glass, but it has very good lighting.', '2004-11-30 16:54:11.000000', NULL, 1),
(1038679, 124493, 24183, '<td valign="top">The comp, give the clock a tilted feeling, I think it would be better if you distubute the fruit dirfently</td>', 'The comp, give the clock a tilted feeling, I think it would be better if you distubute the fruit dirfently', '2004-11-30 16:55:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1038680, 124506, 24183, '<td valign="top">This photo is a little grainy, try setting your ISO to 200 or 400 and increase the light around the subject, unless you were going for a grain effect.</td>', 'This photo is a little grainy, try setting your ISO to 200 or 400 and increase the light around the subject, unless you were going for a grain effect.', '2004-11-30 16:56:30.000000', NULL, 1),
