INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1040327, 122488, 3306, '<td valign="top">Good perspective, well focused, Simple but nicely done. Would have worked well in the Yellow Challenge.</td>', 'Good perspective, well focused, Simple but nicely done. Would have worked well in the Yellow Challenge.', '2004-12-01 07:14:09.000000', NULL, 1),
(1040332, 124972, 3306, '<td valign="top">Very colorful and nicely layed out. I like how you captured the reflections in the knife. Well done.</td>', 'Very colorful and nicely layed out. I like how you captured the reflections in the knife. Well done.', '2004-12-01 07:16:24.000000', NULL, 1),
(1040335, 124609, 3306, '<td valign="top">You have captured some interesting lines and angles.</td>', 'You have captured some interesting lines and angles.', '2004-12-01 07:18:17.000000', NULL, 1),
(1040338, 124371, 3306, '<td valign="top">Well done. I like the way you have selectively desaturated the picture to bring out your subject. If you hadn''t done this my eyes would be drawn to the little boy instead of the wagon. Great way to make your point.</td>', 'Well done. I like the way you have selectively desaturated the picture to bring out your subject. If you hadn''t done this my eyes would be drawn to the little boy instead of the wagon. Great way to make your point.', '2004-12-01 07:20:34.000000', NULL, 1),
(1040340, 123659, 24128, '<td valign="top">nice image but I find the effect on the bars to be distracting</td>', 'nice image but I find the effect on the bars to be distracting', '2004-12-01 07:21:15.000000', NULL, 1),
(1040342, 124671, 3306, '<td valign="top">Nicely positioned to make your point. Not an original idea but very well executed.</td>', 'Nicely positioned to make your point. Not an original idea but very well executed.', '2004-12-01 07:21:50.000000', NULL, 1),
(1040344, 121696, 24128, '<td valign="top">nice image, but the white in the border really is not needed</td>', 'nice image, but the white in the border really is not needed', '2004-12-01 07:22:57.000000', NULL, 1),
(1040346, 122656, 24128, '<td valign="top">the skin looks just a little ''unreal'', perhaps a bit too much ''NeatImage''?</td>', 'the skin looks just a little ''unreal'', perhaps a bit too much ''NeatImage''?', '2004-12-01 07:23:58.000000', NULL, 1),
(1040348, 122545, 3306, '<td valign="top">This is a well executed technically good picture. Lighting and DOF are pulled off as you have planned. Not the most interesting of subjects but clearly satisfies the challenge. Good job.</td>', 'This is a well executed technically good picture. Lighting and DOF are pulled off as you have planned. Not the most interesting of subjects but clearly satisfies the challenge. Good job.', '2004-12-01 07:24:46.000000', NULL, 1),
(1040351, 124968, 3306, '<td valign="top">The subject is simple but I like your imagination and creativity in making it interesting.</td>', 'The subject is simple but I like your imagination and creativity in making it interesting.', '2004-12-01 07:26:40.000000', NULL, 1),
(1040354, 124603, 3306, '<td valign="top">Doesn''t really impress me as Low Tech but it is an excellent picture with great emotion and I really like the colors. I am more interested in a good picture than "The Rules".</td>', 'Doesn''t really impress me as Low Tech but it is an excellent picture with great emotion and I really like the colors. I am more interested in a good picture than "The Rules".', '2004-12-01 07:28:38.000000', NULL, 1),
(1040356, 124153, 3306, '<td valign="top">You have made a not so interesting subject very captivating. You have brought your picture to life by including the flames. Good job on a tough challenge.</td>', 'You have made a not so interesting subject very captivating. You have brought your picture to life by including the flames. Good job on a tough challenge.', '2004-12-01 07:30:26.000000', NULL, 1),
(1040357, 123357, 3306, '<td valign="top">Nicely done and well executed.</td>', 'Nicely done and well executed.', '2004-12-01 07:30:57.000000', NULL, 1),
(1040359, 122656, 3306, '<td valign="top">I really like this picture. In a challenge full of gadgets it brings life and emotion. Great choice of subject to help you stand out.</td>', 'I really like this picture. In a challenge full of gadgets it brings life and emotion. Great choice of subject to help you stand out.', '2004-12-01 07:32:30.000000', NULL, 1),
(1040361, 124942, 29132, '<td valign="top">Nice title. Works well with the challenge theme.</td>', 'Nice title. Works well with the challenge theme.', '2004-12-01 07:34:15.000000', NULL, 1),
(1040363, 123050, 29132, '<td valign="top">A beautiful photo that works well with the challenge theme. Good title.</td>', 'A beautiful photo that works well with the challenge theme. Good title.', '2004-12-01 07:35:02.000000', NULL, 1),
(1040373, 124905, 29132, '<td valign="top">Cute mouse hole effect -- good composition and lighting.</td>', 'Cute mouse hole effect -- good composition and lighting.', '2004-12-01 07:39:24.000000', NULL, 1),
(1040376, 123794, 29132, '<td valign="top">Simple and concise. I like this.</td>', 'Simple and concise. I like this.', '2004-12-01 07:42:31.000000', NULL, 1),
