(1040396, 124888, 27812, '<td valign="top">this is what keep people like me here.... to see masters at work.</td>', 'this is what keep people like me here.... to see masters at work.', '2004-12-01 07:52:36.000000', NULL, 1),
(1040397, 124883, 27812, '<td valign="top">masterful, absolutely masterful. thanks for sharing this masterpiece with us.</td>', 'masterful, absolutely masterful. thanks for sharing this masterpiece with us.', '2004-12-01 07:53:42.000000', NULL, 1),
