(1040402, 121739, 27812, '<td valign="top">impressive quality of photography.</td>', 'impressive quality of photography.', '2004-12-01 07:56:44.000000', NULL, 1),
(1040404, 124654, 27812, '<td valign="top">looking at this again... bumping up, well done, such a fine shot it actually grows on you.</td>', 'looking at this again... bumping up, well done, such a fine shot it actually grows on you.', '2004-12-01 07:58:49.000000', NULL, 1),
