(1040419, 124236, 29132, '<td valign="top">Great lighting effect. This works.</td>', 'Great lighting effect. This works.', '2004-12-01 08:04:45.000000', NULL, 1),
(1040424, 122904, 27812, '<td valign="top">great pic... serves it''s purpose very well. i love the colors.</td>', 'great pic... serves it''s purpose very well. i love the colors.', '2004-12-01 08:06:00.000000', NULL, 1),
(1040427, 124198, 27812, '<td valign="top">bumping up... actually one of the best pics of the entry. great work</td>', 'bumping up... actually one of the best pics of the entry. great work', '2004-12-01 08:06:55.000000', NULL, 1),
(1040434, 121834, 27812, '<td valign="top">this a great subject, but, the focus seems to be not the best. i think also the composition, in this rare case i would have said the rule of thirds, would also have enhanced what could have been a winner.</td>', 'this a great subject, but, the focus seems to be not the best. i think also the composition, in this rare case i would have said the rule of thirds, would also have enhanced what could have been a winner.', '2004-12-01 08:09:32.000000', NULL, 1),
(1040436, 122776, 15811, '<td valign="top">This could quite possibly get top 10 but would definately have gotten top 10 had the lighting been better to let out those colors that I know are there.  Not sure I dig that lightened area around the weather vane (although that probably makes it stand out as was your intent) -- but that''s just personaly preferance.<br/> <br/>The inner glow on the border, I don''t dig either, your entry stands for itself without some fancy border.  Great composition as well, good job!</td>', 'This could quite possibly get top 10 but would definately have gotten top 10 had the lighting been better to let out those colors that I know are there.  Not sure I dig that lightened area around the weather vane (although that probably makes it stand out as was your intent) -- but that''s just personaly preferance. The inner glow on the border, I don''t dig either, your entry stands for itself without some fancy border.  Great composition as well, good job!', '2004-12-01 08:09:58.000000', NULL, 1),
