(1042445, 124260, 22537, '<td valign="top">Interesting shot but the picture is too small. that is my biggest beef.</td>', 'Interesting shot but the picture is too small. that is my biggest beef.', '2004-12-01 22:29:36.000000', NULL, 1),
(1042446, 124972, 22537, '<td valign="top">Vibrant photo and pleasant to look at.</td>', 'Vibrant photo and pleasant to look at.', '2004-12-01 22:30:29.000000', NULL, 1),
