(1042812, 124858, 22479, '<td valign="top">I''m not certain but do these devices contain any electronic circuits within? Well exposed, focused, and composed.</td>', 'I''m not certain but do these devices contain any electronic circuits within? Well exposed, focused, and composed.', '2004-12-02 04:22:02.000000', NULL, 1),
(1042813, 123063, 22479, '<td valign="top">They are still in use. Would you consider a fork or spoon low tech? I''m not sure, but they are probably as ancient.</td>', 'They are still in use. Would you consider a fork or spoon low tech? I''m not sure, but they are probably as ancient.', '2004-12-02 04:23:41.000000', NULL, 1),
(1042814, 124042, 22479, '<td valign="top">I disagree that chopsticks are ''low tech''. You could have easily substituted a spoon or fork in this shot. Sorry.</td>', 'I disagree that chopsticks are ''low tech''. You could have easily substituted a spoon or fork in this shot. Sorry.', '2004-12-02 04:24:41.000000', NULL, 1),
