(1042816, 124545, 22479, '<td valign="top">I''m not certain, but does this not contain electronic circuits? Nice exposure, tonal range, focus, and composition, by the way.</td>', 'I''m not certain, but does this not contain electronic circuits? Nice exposure, tonal range, focus, and composition, by the way.', '2004-12-02 04:26:12.000000', NULL, 1),
(1042818, 123688, 22479, '<td valign="top">Some would argue this is not quite ''low tech''. Be that as it may, the composition is great and the exposure and focus is nice.</td>', 'Some would argue this is not quite ''low tech''. Be that as it may, the composition is great and the exposure and focus is nice.', '2004-12-02 04:27:06.000000', NULL, 1),
(1042820, 124978, 22479, '<td valign="top">Not sure how this is low tech. Hydroelectric energy is certainly as modern as the coal plant, unless I''m way off.</td>', 'Not sure how this is low tech. Hydroelectric energy is certainly as modern as the coal plant, unless I''m way off.', '2004-12-02 04:28:12.000000', NULL, 1),
(1042821, 123713, 22479, '<td valign="top">Funky colors and lighting. Great composition. Not quite what I would consider low tech, but this is a good photograph.</td>', 'Funky colors and lighting. Great composition. Not quite what I would consider low tech, but this is a good photograph.', '2004-12-02 04:28:53.000000', NULL, 1),
(1042822, 124167, 22479, '<td valign="top">I''m not sure but doesn''t this contain electronic circuits? Be that as it may, the composition is good and the focus and lighting is adequate.</td>', 'I''m not sure but doesn''t this contain electronic circuits? Be that as it may, the composition is good and the focus and lighting is adequate.', '2004-12-02 04:29:59.000000', NULL, 1),
