(1042870, 122288, 16241, '<td valign="top">very nice!</td>', 'very nice!', '2004-12-02 07:09:55.000000', NULL, 1),
(1042875, 123777, 16241, '<td valign="top">perfectly sharp, framed</td>', 'perfectly sharp, framed', '2004-12-02 07:14:17.000000', NULL, 1),
(1042876, 122389, 16241, '<td valign="top">good title too</td>', 'good title too', '2004-12-02 07:15:28.000000', NULL, 1),
(1043001, 124167, 8054, '<td valign="top">This is fantastic! Love the soft focus effect and the soft spotlight is also a very nice touch. There are a few cities on that radio that I''d like to visit and go back to (such as Munchen). The one detail that bothers me is the lower right corner but I suppose that was unavoidable. You get an 8 from me! Good job!</td>', 'This is fantastic! Love the soft focus effect and the soft spotlight is also a very nice touch. There are a few cities on that radio that I''d like to visit and go back to (such as Munchen). The one detail that bothers me is the lower right corner but I suppose that was unavoidable. You get an 8 from me! Good job!', '2004-12-02 09:09:24.000000', NULL, 1),
(1043004, 124707, 8054, '<td valign="top">Not quite sure I like the filter/effects you used on this. It appears you''ve reduced the pallette by many colors causing the banding. Is it artistic? Yes. Does it appeal to a broad audience? Perhaps. If it''s one thing I''ve learned here at DPC, it is to make your work appeal to the many not the few and I''m still learning what it is that appeals to the many.</td>', 'Not quite sure I like the filter/effects you used on this. It appears you''ve reduced the pallette by many colors causing the banding. Is it artistic? Yes. Does it appeal to a broad audience? Perhaps. If it''s one thing I''ve learned here at DPC, it is to make your work appeal to the many not the few and I''m still learning what it is that appeals to the many.', '2004-12-02 09:12:39.000000', NULL, 1),
(1043008, 123626, 8054, '<td valign="top">This is rather gross, I''m sorry. I''m sure there were other ways and means to show toothpaste.</td>', 'This is rather gross, I''m sorry. I''m sure there were other ways and means to show toothpaste.', '2004-12-02 09:16:28.000000', NULL, 1),
(1043016, 124336, 3569, '<td valign="top">great sharpness and dof</td>', 'great sharpness and dof', '2004-12-02 09:27:32.000000', NULL, 1),
