(1044103, 123717, 11895, '<td valign="top">I really like this shot, good depth of field, it fits the theme well, but I wish the background wasn''t so light, it seems to fade to almost solid white at the left side, losing all texture</td>', 'I really like this shot, good depth of field, it fits the theme well, but I wish the background wasn''t so light, it seems to fade to almost solid white at the left side, losing all texture', '2004-12-02 22:51:27.000000', NULL, 1),
(1044131, 124987, 12253, '<td valign="top">Great subject matter choice, and very nice shot.  One idea for possible improvement would be to not crop so tight at the top, and to make the drill more visible.  But very nice overall.</td>', 'Great subject matter choice, and very nice shot.  One idea for possible improvement would be to not crop so tight at the top, and to make the drill more visible.  But very nice overall.', '2004-12-02 23:13:32.000000', NULL, 1),
