(1045245, 123626, 12253, '<td valign="top">I like the way you chose to capture this!   Good crop as well.</td>', 'I like the way you chose to capture this!   Good crop as well.', '2004-12-03 20:45:41.000000', NULL, 1),
(1045249, 124883, 12253, '<td valign="top">A very neat pastel sky; the water seems misty too (long exposure?)  But perhaps have a bit more contrast would help bring out the lighthouse and the rocks below it.</td>', 'A very neat pastel sky; the water seems misty too (long exposure?)  But perhaps have a bit more contrast would help bring out the lighthouse and the rocks below it.', '2004-12-03 20:47:44.000000', NULL, 1),
(1045254, 124572, 12253, '<td valign="top">Nice idea and good colors.  I''m more mixed about the shallow DOF here, part of me likes it, part of me wants more in focus.   You may have been torn too!</td>', 'Nice idea and good colors.  I''m more mixed about the shallow DOF here, part of me likes it, part of me wants more in focus.   You may have been torn too!', '2004-12-03 20:50:07.000000', NULL, 1),
(1045257, 124930, 12253, '<td valign="top">Great idea, and an interesting perspective.  I love the straw, but not found of the mix with the leaves on the pitchfork.  I would leave (ha ha ) them out.</td>', 'Great idea, and an interesting perspective.  I love the straw, but not found of the mix with the leaves on the pitchfork.  I would leave (ha ha ) them out.', '2004-12-03 20:51:13.000000', NULL, 1),
