(1045398, 124665, 22384, '<td valign="top">What could be more low tech than muscle, skill, fire and iron? Brilliant choice of subject. Great range of eath tones. Nice use of motif with the iron rods hanging in the background. Excellent piece.</td>', 'What could be more low tech than muscle, skill, fire and iron? Brilliant choice of subject. Great range of eath tones. Nice use of motif with the iron rods hanging in the background. Excellent piece.', '2004-12-03 22:21:12.000000', NULL, 1),
(1045401, 124888, 22384, '<td valign="top">Stunning. The blowing snow is perfect. Outstanding job of meeting the challenge, executing the perfect image, and evoking a mood of the forgotten. A rare 10.</td>', 'Stunning. The blowing snow is perfect. Outstanding job of meeting the challenge, executing the perfect image, and evoking a mood of the forgotten. A rare 10.', '2004-12-03 22:22:53.000000', NULL, 1),
(1045402, 122505, 22384, '<td valign="top">Tis image is so earthy and authentic, except that garden claw: too new and blue. I am sure you added it as a foil to add interest, but I would like the image better without it. Great photo, though. An 8</td>', 'Tis image is so earthy and authentic, except that garden claw: too new and blue. I am sure you added it as a foil to add interest, but I would like the image better without it. Great photo, though. An 8', '2004-12-03 22:24:23.000000', NULL, 1),
(1045405, 124858, 22384, '<td valign="top">I swear we had the same type of camera as the one in the middle of this shot. When I was a little girl, I used to burn my fingers on the bulbs by pulling them out when they were still hot. I had forgotten about that. Great nostalgic touch with the boxes. nice shot.</td>', 'I swear we had the same type of camera as the one in the middle of this shot. When I was a little girl, I used to burn my fingers on the bulbs by pulling them out when they were still hot. I had forgotten about that. Great nostalgic touch with the boxes. nice shot.', '2004-12-03 22:27:28.000000', NULL, 1),
(1045407, 122389, 22384, '<td valign="top">The technical aspects of this shot are stunning for me. I find my strength in artistic elements, and I am still struggling with the technical details of photography. I will be sure to check out your portfolio when I find out who you are after voting. Everything about this shot works for me. The movement of the clapper (is that what it''s called) between the bells is a perfect touch. Captivating shot.</td>', 'The technical aspects of this shot are stunning for me. I find my strength in artistic elements, and I am still struggling with the technical details of photography. I will be sure to check out your portfolio when I find out who you are after voting. Everything about this shot works for me. The movement of the clapper (is that what it''s called) between the bells is a perfect touch. Captivating shot.', '2004-12-03 22:30:33.000000', NULL, 1),
(1045413, 124888, 6600, '<td valign="top">This is my favorite in this challenge.  I am not voting on any photo, but merely commenting.  This would be my ''Blue''.  Very nice job!</td>', 'This is my favorite in this challenge.  I am not voting on any photo, but merely commenting.  This would be my ''Blue''.  Very nice job!', '2004-12-03 22:36:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1045418, 122600, 12253, '<td valign="top">Very good idea, love the tones and the lighting.  I think the what would make this a winning  photo would be a slightly different composition.  The tools are perfect for the theme, but the covered tool is a distraction;  If you could have arranged them a bit on the wall, and then put the horse more in the sweet spot on the left third line, with the tools spread along the bottom from center to right, I think it might have been more effective.  Also, maybe instead of the shovel, which has a hot spot, a harness, or other horse paraphanalia.hanging there.  Or maybe stepping left and shooting from an angle to achieve the similar composition.  Just my own perceptions.</td>', 'Very good idea, love the tones and the lighting.  I think the what would make this a winning  photo would be a slightly different composition.  The tools are perfect for the theme, but the covered tool is a distraction;  If you could have arranged them a bit on the wall, and then put the horse more in the sweet spot on the left third line, with the tools spread along the bottom from center to right, I think it might have been more effective.  Also, maybe instead of the shovel, which has a hot spot, a harness, or other horse paraphanalia.hanging there.  Or maybe stepping left and shooting from an angle to achieve the similar composition.  Just my own perceptions.', '2004-12-03 22:44:06.000000', NULL, 1),
(1045420, 124042, 12253, '<td valign="top">Very nice and simple idea; perhaps some nice black fancy ones would have been a better contrast here.  These look like the cheap wooden ones and don''t even really look like they are oriented right--though I think what I am seeing is the "break-away" area where they are attached together.</td>', 'Very nice and simple idea; perhaps some nice black fancy ones would have been a better contrast here.  These look like the cheap wooden ones and don''t even really look like they are oriented right--though I think what I am seeing is the "break-away" area where they are attached together.', '2004-12-03 22:45:36.000000', NULL, 1),
(1045422, 123240, 12253, '<td valign="top">Very nice idea.  I think it would be nice to get the towel out of there--I think a crop of the left would have worked very well for that, focusing the viewer on the work in progress.</td>', 'Very nice idea.  I think it would be nice to get the towel out of there--I think a crop of the left would have worked very well for that, focusing the viewer on the work in progress.', '2004-12-03 22:47:19.000000', NULL, 1),
(1045424, 124697, 12253, '<td valign="top">Very nice; I like the rustic cabin here a lot, but to me the electric wire and junction box spoil the mood  a little.  I know you were going for the tractor, but if you get back there, perhaps try a different angle on the place.</td>', 'Very nice; I like the rustic cabin here a lot, but to me the electric wire and junction box spoil the mood  a little.  I know you were going for the tractor, but if you get back there, perhaps try a different angle on the place.', '2004-12-03 22:48:48.000000', NULL, 1),
(1045426, 124198, 12253, '<td valign="top">That certainly is low tech and I like the soft edges effect you used here.</td>', 'That certainly is low tech and I like the soft edges effect you used here.', '2004-12-03 22:49:28.000000', NULL, 1),
(1045437, 124819, 12253, '<td valign="top">Good low tech implement, good tones and composition.</td>', 'Good low tech implement, good tones and composition.', '2004-12-03 22:56:06.000000', NULL, 1),
(1045442, 124865, 12253, '<td valign="top">Cool instrument and I love the warm tones.  You may not have noticed but there''s some stray light on your background on the right edge and at the top right of the nut cracker.    Looks like bottom left too but less so on my monitor.  Compositionally, this misses for me; I  think it might have worked better either in portrait format, or back a step, with the nuts in the foreground not "clipped", and perhaps on the left third line.  Or maybe a more diagonal layout of the extra nuts--walking down the diagonal from one sweet spot to another.</td>', 'Cool instrument and I love the warm tones.  You may not have noticed but there''s some stray light on your background on the right edge and at the top right of the nut cracker.    Looks like bottom left too but less so on my monitor.  Compositionally, this misses for me; I  think it might have worked better either in portrait format, or back a step, with the nuts in the foreground not "clipped", and perhaps on the left third line.  Or maybe a more diagonal layout of the extra nuts--walking down the diagonal from one sweet spot to another.', '2004-12-03 22:59:04.000000', NULL, 1),
(1045446, 122003, 12253, '<td valign="top">Nice!  I like the use of the sillouette here, and the sunset and sky adds mood, but the barn/shed/whatever on the left is a distraction in sillouette form.  I think it might have worked better with just the pulley device.</td>', 'Nice!  I like the use of the sillouette here, and the sunset and sky adds mood, but the barn/shed/whatever on the left is a distraction in sillouette form.  I think it might have worked better with just the pulley device.', '2004-12-03 23:00:26.000000', NULL, 1),
(1045447, 123484, 29477, '<td valign="top">I like your brightness adjustments.  I really enjoy the illusion of the white typewriter keys and seeing the letters in the reflection. good entry.</td>', 'I like your brightness adjustments.  I really enjoy the illusion of the white typewriter keys and seeing the letters in the reflection. good entry.', '2004-12-03 23:00:43.000000', NULL, 1),
(1045449, 122488, 12253, '<td valign="top">Cute shot, simple low tech device.  I like the high key here, and the angle.  I am more mixed about the foreground texture--is this sitting on a bedspread?</td>', 'Cute shot, simple low tech device.  I like the high key here, and the angle.  I am more mixed about the foreground texture--is this sitting on a bedspread?', '2004-12-03 23:01:33.000000', NULL, 1),
(1045452, 124145, 29477, '<td valign="top">Nice composition and lighting.  Simple and to the point.  Better of the other cassette tape entry.</td>', 'Nice composition and lighting.  Simple and to the point.  Better of the other cassette tape entry.', '2004-12-03 23:02:19.000000', NULL, 1),
(1045454, 124292, 12253, '<td valign="top">I was thinking about an abacus for this challenge--good idea.  I like the dark background and the lighting; I think it could have been made more interesting perhaps by spreading out the balls as if a calculation were being performed.</td>', 'I was thinking about an abacus for this challenge--good idea.  I like the dark background and the lighting; I think it could have been made more interesting perhaps by spreading out the balls as if a calculation were being performed.', '2004-12-03 23:02:58.000000', NULL, 1),
(1045483, 124153, 12253, '<td valign="top">Very cool device (or very hot!).  Great for Low Tech.  Capture is very good, lighting is good, but I think the composition is a bit cramped at the left, and also, but less so, at right and bottom.  I think stepping back and capturing a bit more negative space would have worked here.</td>', 'Very cool device (or very hot!).  Great for Low Tech.  Capture is very good, lighting is good, but I think the composition is a bit cramped at the left, and also, but less so, at right and bottom.  I think stepping back and capturing a bit more negative space would have worked here.', '2004-12-03 23:29:57.000000', NULL, 1),
(1045484, 124967, 12253, '<td valign="top">Very nice lighting, good capture of the motion, and good idea.  The only thing that might have improved this in my eyes is the inclusion of an operator.</td>', 'Very nice lighting, good capture of the motion, and good idea.  The only thing that might have improved this in my eyes is the inclusion of an operator.', '2004-12-03 23:31:22.000000', NULL, 1),
(1045491, 124167, 12253, '<td valign="top">I like the angle you shot this at, the colors and soft look you''ve captured.  I''m not exactly sure what I''m looking at: either an old radio or shortwave radio, I presume.  I think stepping back a bit (or cropping less) might have helped me identify it more quickly.  My own views aside, but you are probably taking a beating on this as this is an electronic device (challenge said non-electronic).  But it''s stil a nice photo (and I scored it well anyway.)</td>', 'I like the angle you shot this at, the colors and soft look you''ve captured.  I''m not exactly sure what I''m looking at: either an old radio or shortwave radio, I presume.  I think stepping back a bit (or cropping less) might have helped me identify it more quickly.  My own views aside, but you are probably taking a beating on this as this is an electronic device (challenge said non-electronic).  But it''s stil a nice photo (and I scored it well anyway.)', '2004-12-03 23:36:15.000000', NULL, 1),
(1045501, 124545, 12253, '<td valign="top">Nice idea for the challenge.  This would have shown much better though with a black background, and maybe some more diffuse lighting.    Perhaps a bit of a perspective shot would have been cool as well--that''s a big lens for that camera!</td>', 'Nice idea for the challenge.  This would have shown much better though with a black background, and maybe some more diffuse lighting.    Perhaps a bit of a perspective shot would have been cool as well--that''s a big lens for that camera!', '2004-12-03 23:41:35.000000', NULL, 1),
(1045506, 121880, 12253, '<td valign="top">Yes, those are low tech office goods, nice color contrasts too.  Works somewhat as a geometric abstract.  But I think this could have been arranged and shot even more creatively.</td>', 'Yes, those are low tech office goods, nice color contrasts too.  Works somewhat as a geometric abstract.  But I think this could have been arranged and shot even more creatively.', '2004-12-03 23:44:19.000000', NULL, 1),
(1045509, 123713, 12253, '<td valign="top">Nice guitar capture; the movement capture is a good idea, but seems more "blurry" than movement blur.  Looks like too little DOF (I do understand it was dark there).    As to the challenge theme, an electric guitar is "electronic" and not very low tech!</td>', 'Nice guitar capture; the movement capture is a good idea, but seems more "blurry" than movement blur.  Looks like too little DOF (I do understand it was dark there).    As to the challenge theme, an electric guitar is "electronic" and not very low tech!', '2004-12-03 23:46:21.000000', NULL, 1),
(1045511, 124893, 12253, '<td valign="top">I had one of those when I was little.... fun, low tech toy.  I like the black and white here, and the kid''s expression is cute, but I think this would have worked better as a tight crop, showing the face, the ensignia, and perhaps the wheels.  The grass is just too boring, and yet distracting, a background for this.</td>', 'I had one of those when I was little.... fun, low tech toy.  I like the black and white here, and the kid''s expression is cute, but I think this would have worked better as a tight crop, showing the face, the ensignia, and perhaps the wheels.  The grass is just too boring, and yet distracting, a background for this.', '2004-12-03 23:48:11.000000', NULL, 1),
(1045515, 124926, 12253, '<td valign="top">As a cyclist, I''m drawn to this image.  I think the B&amp;W conversion was great, and it''s wonderfully sharp.  I think it might have been nice to get it further away from the wall before shooting.  The peeling paint is competing to steal my attention.</td>', 'As a cyclist, I''m drawn to this image.  I think the B&W conversion was great, and it''s wonderfully sharp.  I think it might have been nice to get it further away from the wall before shooting.  The peeling paint is competing to steal my attention.', '2004-12-03 23:49:28.000000', NULL, 1),
(1045666, 123484, 16241, '<td valign="top">yes, hope you do well :)</td>', 'yes, hope you do well :)', '2004-12-04 02:31:54.000000', NULL, 1),
(1045667, 124776, 16241, '<td valign="top">nice idea</td>', 'nice idea', '2004-12-04 02:33:04.000000', NULL, 1),
(1045670, 124054, 16241, '<td valign="top">gorgeous portrait</td>', 'gorgeous portrait', '2004-12-04 02:34:25.000000', NULL, 1),
(1045678, 123451, 22011, '<td valign="top">Hopefully not too many people will vote this down for having electricity in it...  It''s not strictly electronics, and this is a great photo..  It has a very other world feel to it.. It''s like a painting almost..  Great Photo.. 9.</td>', 'Hopefully not too many people will vote this down for having electricity in it...  It''s not strictly electronics, and this is a great photo..  It has a very other world feel to it.. It''s like a painting almost..  Great Photo.. 9.', '2004-12-04 02:56:31.000000', NULL, 1),
(1045683, 124888, 16046, '<td valign="top">Outstanding work, my favorite. 10</td>', 'Outstanding work, my favorite. 10', '2004-12-04 03:05:18.000000', NULL, 1),
(1045684, 122552, 16046, '<td valign="top">Very good, well done</td>', 'Very good, well done', '2004-12-04 03:05:52.000000', NULL, 1),
(1045685, 124371, 16046, '<td valign="top">awesome, well done</td>', 'awesome, well done', '2004-12-04 03:06:18.000000', NULL, 1),
(1045686, 122505, 16046, '<td valign="top">almost perfect, if it wasn''t for the plastic handle to the right, well done</td>', 'almost perfect, if it wasn''t for the plastic handle to the right, well done', '2004-12-04 03:07:20.000000', NULL, 1),
(1045688, 123717, 16046, '<td valign="top">good work, nice piece</td>', 'good work, nice piece', '2004-12-04 03:07:55.000000', NULL, 1),
(1045689, 124153, 16046, '<td valign="top">very cool, I mean hot, well done</td>', 'very cool, I mean hot, well done', '2004-12-04 03:08:25.000000', NULL, 1),
(1045690, 124665, 16046, '<td valign="top">B &amp; W would have made this fine entry even better.</td>', 'B & W would have made this fine entry even better.', '2004-12-04 03:09:11.000000', NULL, 1),
(1045691, 124863, 16046, '<td valign="top">good find</td>', 'good find', '2004-12-04 03:09:30.000000', NULL, 1),
(1045707, 124701, 29486, '<td valign="top">I think I would have liked the subject to fill up the photo more</td>', 'I think I would have liked the subject to fill up the photo more', '2004-12-04 03:45:26.000000', NULL, 1),
(1045708, 121880, 29486, '<td valign="top">Nothing terribly attractive here. The item is on top of the paper so it casts heavy shadows that do nothing to help it.</td>', 'Nothing terribly attractive here. The item is on top of the paper so it casts heavy shadows that do nothing to help it.', '2004-12-04 03:46:25.000000', NULL, 1),
(1045709, 122775, 29486, '<td valign="top">Avg. photo of a bridge. It is very hard to distinguish it from it''s surroundings.</td>', 'Avg. photo of a bridge. It is very hard to distinguish it from it''s surroundings.', '2004-12-04 03:47:15.000000', NULL, 1),
(1045711, 124967, 29486, '<td valign="top">Nice colors. Clear. Has some action to it. Not bad at all.</td>', 'Nice colors. Clear. Has some action to it. Not bad at all.', '2004-12-04 03:48:00.000000', NULL, 1),
(1045712, 124930, 29486, '<td valign="top">Interesting angle. Unfortunately you can hardly see the object and instead see the results of it which somewhat blend into the background.</td>', 'Interesting angle. Unfortunately you can hardly see the object and instead see the results of it which somewhat blend into the background.', '2004-12-04 03:49:24.000000', NULL, 1),
(1045713, 124336, 29486, '<td valign="top">Nice attempt at making a boring item interesting. Not too fond of the shadows though. They really take my eye away from the subject.</td>', 'Nice attempt at making a boring item interesting. Not too fond of the shadows though. They really take my eye away from the subject.', '2004-12-04 03:50:30.000000', NULL, 1),
(1045714, 124145, 29486, '<td valign="top">Good color, nice shadows. Makes a simple item look interesting.</td>', 'Good color, nice shadows. Makes a simple item look interesting.', '2004-12-04 03:51:18.000000', NULL, 1),
(1045715, 123977, 29486, '<td valign="top">I''m guessing this was a hard shot. It came out pretty good though.  Not the most interesting picture but A for effort.</td>', 'I''m guessing this was a hard shot. It came out pretty good though.  Not the most interesting picture but A for effort.', '2004-12-04 03:52:11.000000', NULL, 1),
(1045717, 123522, 29486, '<td valign="top">Subject really jumps out at you. Nice job.</td>', 'Subject really jumps out at you. Nice job.', '2004-12-04 03:52:47.000000', NULL, 1),
(1045718, 124136, 29486, '<td valign="top">Good angle. It makes the light interesting.</td>', 'Good angle. It makes the light interesting.', '2004-12-04 03:54:12.000000', NULL, 1),
(1045719, 121739, 29486, '<td valign="top">The metal reflects quite nicely. Nice shot.</td>', 'The metal reflects quite nicely. Nice shot.', '2004-12-04 03:54:42.000000', NULL, 1),
(1045720, 122762, 29486, '<td valign="top">All kinds of lines but the contrast of the photo just makes it look dreary</td>', 'All kinds of lines but the contrast of the photo just makes it look dreary', '2004-12-04 03:55:34.000000', NULL, 1),
(1045721, 123756, 29486, '<td valign="top">Feels like a snap shot. Could it be the computer book it''s sitting on?</td>', 'Feels like a snap shot. Could it be the computer book it''s sitting on?', '2004-12-04 03:56:55.000000', NULL, 1),
(1045722, 121775, 29486, '<td valign="top">Looks nice all around.</td>', 'Looks nice all around.', '2004-12-04 03:57:18.000000', NULL, 1),
(1045723, 124586, 29486, '<td valign="top">The item is lost in the leaves.  Apparently the leaves are more important since they take up about 80% of the photo.</td>', 'The item is lost in the leaves.  Apparently the leaves are more important since they take up about 80% of the photo.', '2004-12-04 03:58:14.000000', NULL, 1),
(1045724, 122288, 29486, '<td valign="top">Nice use of contrast. Not super interesting but the shadows and such give it some character.</td>', 'Nice use of contrast. Not super interesting but the shadows and such give it some character.', '2004-12-04 03:59:12.000000', NULL, 1),
(1045728, 124592, 29486, '<td valign="top">The part of the object you''re showing seems to me to be the least interesting part.  I think I want to see it from the front, maybe looking down the barrel.</td>', 'The part of the object you''re showing seems to me to be the least interesting part.  I think I want to see it from the front, maybe looking down the barrel.', '2004-12-04 04:02:08.000000', NULL, 1),
(1045729, 124888, 29486, '<td valign="top">Whew, very nice.  Great angle. Beautiful color. The subject just stands right out from the rest of the picture.</td>', 'Whew, very nice.  Great angle. Beautiful color. The subject just stands right out from the rest of the picture.', '2004-12-04 04:03:46.000000', NULL, 1),
(1045730, 122904, 29486, '<td valign="top">Good clarity. There isn''t much interesting about this picture though.</td>', 'Good clarity. There isn''t much interesting about this picture though.', '2004-12-04 04:05:15.000000', NULL, 1),
(1045731, 123906, 29486, '<td valign="top">I like the way the photo is composed. Without the smoke, the photo would be really dull. With it it''s OK.</td>', 'I like the way the photo is composed. Without the smoke, the photo would be really dull. With it it''s OK.', '2004-12-04 04:06:31.000000', NULL, 1),
(1045732, 122505, 29486, '<td valign="top">I like everything about the photo, lighting, color, texture, EXCEPT that it looks staged.</td>', 'I like everything about the photo, lighting, color, texture, EXCEPT that it looks staged.', '2004-12-04 04:08:05.000000', NULL, 1),
(1045733, 124757, 29486, '<td valign="top">Could be an interesting item if I knew what it was. It melds in with the desk. Given the attire of the gentleman, I would think it was going to be a car but I don''t think so. Bad angle for the shot.</td>', 'Could be an interesting item if I knew what it was. It melds in with the desk. Given the attire of the gentleman, I would think it was going to be a car but I don''t think so. Bad angle for the shot.', '2004-12-04 04:09:36.000000', NULL, 1),
(1045734, 124832, 29486, '<td valign="top">I guess you had to shoot close up so we could read the text but it does nothing for the doll which just looks like a mess of colors.</td>', 'I guess you had to shoot close up so we could read the text but it does nothing for the doll which just looks like a mess of colors.', '2004-12-04 04:11:00.000000', NULL, 1),
(1045735, 124292, 29486, '<td valign="top">Good lighting gives this object interest. Nice job.</td>', 'Good lighting gives this object interest. Nice job.', '2004-12-04 04:11:45.000000', NULL, 1),
(1045736, 124925, 29486, '<td valign="top">Nicely done to give this simple object some character</td>', 'Nicely done to give this simple object some character', '2004-12-04 04:12:59.000000', NULL, 1),
(1045737, 124603, 29486, '<td valign="top">Uh, doesn''t look like anything Low Tech to me</td>', 'Uh, doesn''t look like anything Low Tech to me', '2004-12-04 04:13:40.000000', NULL, 1),
(1045740, 122656, 29486, '<td valign="top">At first glance I thought wow. After looking at it for a few seconds though I was bothered. It appears as though she is holding the flute at something like a 30 degree angle upwards vs. horizontal to the ground. The intent no doubt was to highlight the flute. It does make it seem a bit unnatural for me.</td>', 'At first glance I thought wow. After looking at it for a few seconds though I was bothered. It appears as though she is holding the flute at something like a 30 degree angle upwards vs. horizontal to the ground. The intent no doubt was to highlight the flute. It does make it seem a bit unnatural for me.', '2004-12-04 04:16:11.000000', NULL, 1),
(1045742, 124351, 29486, '<td valign="top">Too much background. The books almost seem like clutter when in fact I believe they should have been more of the subject.</td>', 'Too much background. The books almost seem like clutter when in fact I believe they should have been more of the subject.', '2004-12-04 04:19:09.000000', NULL, 1),
(1045743, 123484, 29486, '<td valign="top">Very nice job with the contrast</td>', 'Very nice job with the contrast', '2004-12-04 04:20:07.000000', NULL, 1),
(1045744, 124464, 29486, '<td valign="top">Is the wall that is tucked way in the background that occupies about 3% of the photo supposed to be the subject?  Not good.</td>', 'Is the wall that is tucked way in the background that occupies about 3% of the photo supposed to be the subject?  Not good.', '2004-12-04 04:21:32.000000', NULL, 1),
(1045745, 124148, 29486, '<td valign="top">Can''t say this is very interesting</td>', 'Can''t say this is very interesting', '2004-12-04 04:22:42.000000', NULL, 1),
(1045746, 124931, 29486, '<td valign="top">Nice angle, layout, lighting.</td>', 'Nice angle, layout, lighting.', '2004-12-04 04:23:18.000000', NULL, 1),
(1045748, 124865, 29486, '<td valign="top">Why all the blank space on the right?  You clustered all the nuts in the middle.</td>', 'Why all the blank space on the right?  You clustered all the nuts in the middle.', '2004-12-04 04:25:13.000000', NULL, 1),
(1045749, 124545, 29486, '<td valign="top">Not low tech. Old yes.</td>', 'Not low tech. Old yes.', '2004-12-04 04:26:44.000000', NULL, 1),
(1045750, 123681, 29486, '<td valign="top">Looks like a lot of clutter with very little focus. Everything is stuffed on the bottom part of the image with a gaping hole in the middle.</td>', 'Looks like a lot of clutter with very little focus. Everything is stuffed on the bottom part of the image with a gaping hole in the middle.', '2004-12-04 04:27:45.000000', NULL, 1),
(1045751, 124502, 29486, '<td valign="top">Great item, just not shot in an interesting way.</td>', 'Great item, just not shot in an interesting way.', '2004-12-04 04:30:42.000000', NULL, 1),
(1045752, 121816, 29486, '<td valign="top">You seem more interested in the texture of the metal than the watch itself. If that is the case, why not really zoom in on it so we can see it?</td>', 'You seem more interested in the texture of the metal than the watch itself. If that is the case, why not really zoom in on it so we can see it?', '2004-12-04 04:31:38.000000', NULL, 1),
(1045753, 124932, 29486, '<td valign="top">Would have liked a much better angle on this</td>', 'Would have liked a much better angle on this', '2004-12-04 04:32:41.000000', NULL, 1),
(1045842, 124930, 18191, '<td valign="top">Nice choice of background here as well as good action in the foreground. 10.</td>', 'Nice choice of background here as well as good action in the foreground. 10.', '2004-12-04 09:46:47.000000', NULL, 1),
(1045920, 124707, 30224, '<td valign="top">I think this is a rather interesting image, especially the flow of colours and the gushing efect. The line up the top left bothers my eye though. Otherwise quite unusual.<br/></td>', 'I think this is a rather interesting image, especially the flow of colours and the gushing efect. The line up the top left bothers my eye though. Otherwise quite unusual.', '2004-12-04 11:21:46.000000', NULL, 1),
(1045922, 124145, 11793, '<td valign="top">this most definately - electronic...<br/> <br/>interesting lighting.<br/></td>', 'this most definately - electronic... interesting lighting.', '2004-12-04 11:22:47.000000', NULL, 1),
(1045923, 124906, 30224, '<td valign="top">I love Lego. Really like the angle of the light and shadow on this one.</td>', 'I love Lego. Really like the angle of the light and shadow on this one.', '2004-12-04 11:23:28.000000', NULL, 1),
(1045926, 124336, 11793, '<td valign="top">well composed photo.<br/>i used the same subject.<br/> <br/></td>', 'well composed photo.i used the same subject. ', '2004-12-04 11:29:44.000000', NULL, 1),
(1045929, 124983, 11793, '<td valign="top">even though it''s an old phone, i would still consider electronic.<br/></td>', 'even though it''s an old phone, i would still consider electronic.', '2004-12-04 11:31:01.000000', NULL, 1),
(1046128, 124363, 4517, '<td valign="top">Good set up and colour. 8</td>', 'Good set up and colour. 8', '2004-12-04 15:45:00.000000', NULL, 1),
