(1046135, 124967, 4517, '<td valign="top">Very clean and well lit image and interesting too. 10</td>', 'Very clean and well lit image and interesting too. 10', '2004-12-04 15:49:15.000000', NULL, 1),
(1046141, 123713, 4517, '<td valign="top">Excellent photo but doesn`t look low tech.</td>', 'Excellent photo but doesn`t look low tech.', '2004-12-04 15:53:29.000000', NULL, 1),
(1046166, 124983, 26679, '<td valign="top">The idea is good, but I feel that the general condition of the dial and the low lighting, gives a very grainy and dark feel which does not give this image justice</td>', 'The idea is good, but I feel that the general condition of the dial and the low lighting, gives a very grainy and dark feel which does not give this image justice', '2004-12-04 16:04:12.000000', NULL, 1),
(1046173, 122552, 26679, '<td valign="top">This is a great image,and I feel you have got the tonal, and colour balance just right for me.<br/>For a stronger composition I would have cropped the image off centre, with more space to the left.</td>', 'This is a great image,and I feel you have got the tonal, and colour balance just right for me.For a stronger composition I would have cropped the image off centre, with more space to the left.', '2004-12-04 16:06:16.000000', NULL, 1),
(1046177, 124198, 26679, '<td valign="top">I have never seen a dustpan and brush looking so good.</td>', 'I have never seen a dustpan and brush looking so good.', '2004-12-04 16:07:19.000000', NULL, 1),
(1046179, 124336, 26679, '<td valign="top">Simple idea, elegently done....</td>', 'Simple idea, elegently done....', '2004-12-04 16:07:53.000000', NULL, 1),
(1046183, 121816, 26679, '<td valign="top">Different play on the watch theme, and I good idea. I wonder what is going on top left, what has been partially cropped out.</td>', 'Different play on the watch theme, and I good idea. I wonder what is going on top left, what has been partially cropped out.', '2004-12-04 16:09:56.000000', NULL, 1),
(1046184, 124888, 26679, '<td valign="top">You have evoked a great feeling of abondonment and solitude here. Well done.</td>', 'You have evoked a great feeling of abondonment and solitude here. Well done.', '2004-12-04 16:11:00.000000', NULL, 1),
(1046187, 124905, 20771, '<td valign="top">Taking this from the viewpoint of the mouse was an admirable notion.</td>', 'Taking this from the viewpoint of the mouse was an admirable notion.', '2004-12-04 16:11:55.000000', NULL, 1),
(1046189, 124084, 20771, '<td valign="top">I find the out of focus wagon weakens the picture. It distracts from the pegged posts.</td>', 'I find the out of focus wagon weakens the picture. It distracts from the pegged posts.', '2004-12-04 16:13:44.000000', NULL, 1),
(1046191, 122882, 26679, '<td valign="top">This has some great compositional themes, which for me are not developed sufficiently because of a rather narrow tonal range. <br/> <br/>I would prefer to see more contrast in this image.</td>', 'This has some great compositional themes, which for me are not developed sufficiently because of a rather narrow tonal range.  I would prefer to see more contrast in this image.', '2004-12-04 16:14:33.000000', NULL, 1),
(1046194, 124763, 26679, '<td valign="top">Great composition, and a very simple placement of objects which for me are well lit. and look good.</td>', 'Great composition, and a very simple placement of objects which for me are well lit. and look good.', '2004-12-04 16:16:09.000000', NULL, 1),
(1046198, 123240, 20771, '<td valign="top">Very cool.</td>', 'Very cool.', '2004-12-04 16:18:04.000000', NULL, 1),
(1046206, 124506, 20771, '<td valign="top">The skin tones in the face and the hand are unacceptably noisy and there is also some image breakdown in the eyes and the lips. Without these faults this would be a beautiful picture. she is certainly a beautiful little girl.</td>', 'The skin tones in the face and the hand are unacceptably noisy and there is also some image breakdown in the eyes and the lips. Without these faults this would be a beautiful picture. she is certainly a beautiful little girl.', '2004-12-04 16:23:31.000000', NULL, 1),
(1046211, 122161, 20771, '<td valign="top">With a longer exposure you might have gotten the sand dropping.</td>', 'With a longer exposure you might have gotten the sand dropping.', '2004-12-04 16:27:28.000000', NULL, 1),
(1046213, 123656, 20771, '<td valign="top">Too sophisticated for low tech.  I also think you cropped too tightly.</td>', 'Too sophisticated for low tech.  I also think you cropped too tightly.', '2004-12-04 16:28:29.000000', NULL, 1),
(1046215, 124967, 20771, '<td valign="top">Did you use a strobe to get the spoke image?</td>', 'Did you use a strobe to get the spoke image?', '2004-12-04 16:29:23.000000', NULL, 1),
(1046220, 124502, 20771, '<td valign="top">This picture was very wellcomposed  to include all the elements of the mechanism. However,  the color balance seems to be off in this picture. Too blue.</td>', 'This picture was very wellcomposed  to include all the elements of the mechanism. However,  the color balance seems to be off in this picture. Too blue.', '2004-12-04 16:34:37.000000', NULL, 1),
(1046342, 124236, 25355, '<td valign="top">Another picture of a dictionary page. It''s low-tech, certainly, but not very interesting.</td>', 'Another picture of a dictionary page. It''s low-tech, certainly, but not very interesting.', '2004-12-04 19:05:54.000000', NULL, 1),
(1046343, 124506, 25355, '<td valign="top">Cute girl, but the photo is a bit grainy and the spot editing is too obvious.</td>', 'Cute girl, but the photo is a bit grainy and the spot editing is too obvious.', '2004-12-04 19:10:37.000000', NULL, 1),
(1046345, 124832, 25355, '<td valign="top">Low-tech or no-tech?  Is it really a doll, or just a cushion with a couple of buttons sown on?</td>', 'Low-tech or no-tech?  Is it really a doll, or just a cushion with a couple of buttons sown on?', '2004-12-04 19:13:51.000000', NULL, 1),
