(1049280, 124603, 11793, '<td valign="top">non-electronic?<br/>low tech?<br/> <br/> <br/></td>', 'non-electronic?low tech?  ', '2004-12-06 19:16:28.000000', NULL, 1),
(1049287, 122388, 17203, '<td valign="top">Yeah, it''s low tech, it''s an interesting object, the lighting and color are great and... I''ll bet you''re wondering why your score isn''t higher. Well, you''ve got a centered object on black, with nothing else around it- kinda'' like a catalog photo. There''s no <i>story.</i> This would be SO much more interesting in an environment... such as pouring tea into a handmade cup with bamboo implements around it and soft candlelight. That would lend your image more feeling, and likely a better score. Of course, you might already have a 6.35, in which case you should pretend this was all written in Cherokee and pronounced, "Blah, blah, blah..." ;-)</td>', 'Yeah, it''s low tech, it''s an interesting object, the lighting and color are great and... I''ll bet you''re wondering why your score isn''t higher. Well, you''ve got a centered object on black, with nothing else around it- kinda'' like a catalog photo. There''s no story. This would be SO much more interesting in an environment... such as pouring tea into a handmade cup with bamboo implements around it and soft candlelight. That would lend your image more feeling, and likely a better score. Of course, you might already have a 6.35, in which case you should pretend this was all written in Cherokee and pronounced, "Blah, blah, blah..." ;-)', '2004-12-06 19:18:14.000000', NULL, 1),
(1049292, 124637, 17203, '<td valign="top">I <i>knew</i> this challenge was rigged. Nice color and choice of subject. A leeeetle more focus on that gray rope would have been nice.</td>', 'I knew this challenge was rigged. Nice color and choice of subject. A leeeetle more focus on that gray rope would have been nice.', '2004-12-06 19:20:03.000000', NULL, 1),
(1049298, 124931, 17203, '<td valign="top">A cassette tape may be old, but reading data off magnetic tape is still pretty darn high tech.</td>', 'A cassette tape may be old, but reading data off magnetic tape is still pretty darn high tech.', '2004-12-06 19:23:24.000000', NULL, 1),
(1049308, 123688, 17203, '<td valign="top">Wow, a bean counter with actual beans! Good choice for the challenge. The pixelated edges are distracting, and the corner at top right is an awkward crop, but color and composition are good.</td>', 'Wow, a bean counter with actual beans! Good choice for the challenge. The pixelated edges are distracting, and the corner at top right is an awkward crop, but color and composition are good.', '2004-12-06 19:27:12.000000', NULL, 1),
(1049324, 123484, 17203, '<td valign="top">Very clever. The keys may have crossed the line from high-key to just overexposed, and the cropping is a little tight on the sides, but how can I ignore such a great concept? 8</td>', 'Very clever. The keys may have crossed the line from high-key to just overexposed, and the cropping is a little tight on the sides, but how can I ignore such a great concept? 8', '2004-12-06 19:46:14.000000', NULL, 1),
